CREATE DATABASE IF NOT EXISTS encontro CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE encontro;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, firebase_uid VARCHAR(128) NOT NULL UNIQUE, email VARCHAR(254) NOT NULL, name VARCHAR(120) NOT NULL DEFAULT '', phone VARCHAR(25) NOT NULL DEFAULT '', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE spaces (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, capacity INT UNSIGNED NOT NULL, daily_price DECIMAL(10,2) NOT NULL, weekend_price DECIMAL(10,2) NULL COMMENT 'Pacote de 48h; NULL usa duas diárias', city VARCHAR(120) NOT NULL, type VARCHAR(40) NOT NULL);
CREATE TABLE reservations (id CHAR(32) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,space_id BIGINT UNSIGNED NOT NULL,event_date DATE NOT NULL,check_in DATETIME NOT NULL,check_out DATETIME NOT NULL,plan ENUM('daily','weekend') NOT NULL DEFAULT 'daily',billable_days INT UNSIGNED NOT NULL,contact_name VARCHAR(120) NOT NULL,guests INT UNSIGNED NOT NULL,phone VARCHAR(25) NOT NULL,message TEXT NOT NULL,total DECIMAL(10,2) NOT NULL,status ENUM('creating','pending','approved','failed','cancelled') NOT NULL DEFAULT 'creating',preference_id VARCHAR(100),payment_id VARCHAR(100),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(space_id) REFERENCES spaces(id),INDEX availability(space_id,status,check_in,check_out),CHECK(check_out > check_in));
